select o.status, case when o.amount >= 1350 then 'high' when o.amount >= 650 then 'mid' else 'low' end as amount_bucket, concat_ws(', ', sort_array(collect_set(p.method))) as method_values, count(case when p.status = 'SUCCESS' then 1 end) as success_count from payments p inner join orders o on p.order_id = o.id group by o.status, case when o.amount >= 1350 then 'high' when o.amount >= 650 then 'mid' else 'low' end order by method_values, status, amount_bucket limit 10;
